def from_csv(file_path):
    with codecs.open('202509241.csv', 'r', encoding='utf-8-sig') as f:
        # with open(file_path, 'r') as f:
        csv_reader = csv.DictReader(f)
        datas = []
        for row in csv_reader:
            # print  row
            datas.append(int(row['serial_id']))
    return datas


