whitelist_collection = []
# -*- coding: utf-8 -*-
import xlrd

def read_excel(file_path):
    # 打开 Excel 文件
    workbook = xlrd.open_workbook(file_path)

    # 获取第一个 sheet
    sheet = workbook.sheet_by_index(0)

    # 遍历行
    for row_idx in range(1, sheet.nrows):
        row_values = sheet.row_values(row_idx)
        cell_value = str(row_values[1]).strip()
        if cell_value.upper() == 'YES':
            whitelist_collection.append(int(row_values[0]))
    print(list(whitelist_collection))
    print(len(whitelist_collection))


def check_non_float_fields(app_config):
    """
    检查 ltv 和 coverage 字段中不为 float 类型的记录

    Args:
        app_config: app配置字典

    Returns:
        包含异常字段的列表
    """
    non_float_records = []

    for app_id, config in app_config.items():
        # 检查 ltv 字段
        ltv_value = config.get('ltv')
        if ltv_value is not None and not isinstance(ltv_value, float):
            non_float_records.append({
                'app_id': app_id,
                'field': 'ltv',
                'value': ltv_value,
                'type': type(ltv_value).__name__
            })

        # 检查 coverage 字段
        coverage_value = config.get('coverage')
        if coverage_value is not None and not isinstance(coverage_value, float):
            non_float_records.append({
                'app_id': app_id,
                'field': 'coverage',
                'value': coverage_value,
                'type': type(coverage_value).__name__
            })

    return non_float_records

def readcsv1(file_path):
    # 打开CSV文件
    app_config = {}
    with open(file_path) as file:
        # 创建CSV读取器
        csv_reader = csv.reader(file)

        # 跳过表头（第1行）
        next(csv_reader)
        """
        finance
        good_competitor
        100w+_competitor
        tgi
        ltv
        coverage
        released_unix
        """
        # 逐行读取数据
        for row in csv_reader:
            if not row:
                return app_config

            # 转换数值类型，保持精度
            def convert_value(value):
                try:
                    # 先尝试转换为整数
                    if '.' not in value:
                        return int(value)
                    # 再尝试转换为浮点数
                    return float(value)
                except (ValueError, TypeError):
                    # 如果转换失败，返回原字符串
                    return value
            # todo 检查下 ltv  coverage 不为float的字段
            app_config[row[0]] = {
                'genre': row[1],
                'finance': row[2],
                'good_competitor': convert_value(row[3]),
                '100w_competitor': convert_value(row[4]),
                'tgi': convert_value(row[5]),
                'ltv': float(convert_value(row[6])) if convert_value(row[6]) else None,
                'coverage': float(convert_value(row[7])),
                'released_unix': int(convert_value(row[8])) if row[8] else 0
            }
        # 检查 ltv 和 coverage 字段中不为 float 的记录
        non_float_records = check_non_float_fields(app_config)
        if non_float_records:
            print("发现 {} 条 ltv 或 coverage 不为 float 的记录:".format(len(non_float_records)))
            for record in non_float_records:
                print("  App ID: {}, 字段: {}, 值: {}, 类型: {}".format(
                    record['app_id'],
                    record['field'],
                    record['value'],
                    record['type']
                ))
        else:
            print("所有 ltv 和 coverage 字段均为 float 类型")

        # print len(app_config)
        # todo 将app_config写入文件  app_config.json
        with open('mx_competitor_app_behavior_v1_fea.json', 'w') as f:
            json.dump(app_config, f, ensure_ascii=False)
        # print json.dumps(app_config, ensure_ascii=False)
        return app_config


